import csv,collections,statistics as st
D='/home/user/crux-lab/topics-r2/machine/rent-buy-1/data/'
def load(n):
    out={}
    for r in csv.DictReader(open(D+n+'.csv')):
        v=r[n]
        if v not in ('','.'): out[r['observation_date'][:7]]=float(v)
    return out
I=load('HPIPONM226N');C=load('CUUR0000SEHA');T=load('TB3MS')
w=collections.defaultdict(list)
for r in csv.DictReader(open(D+'MORTGAGE30US.csv')):
    if r['MORTGAGE30US'] not in ('','.'): w[r['observation_date'][:7]].append(float(r['MORTGAGE30US']))
R={k:sum(v)/len(v) for k,v in w.items()}
months=sorted(I)
def add(m,k):
    y,mm=map(int,m.split('-')); t=y*12+mm-1+k; return f"{t//12:04d}-{t%12+1:02d}"
anchor='2026-07'
def run(H,yA=0.05,c=0.025,tb=False,fixed=False):
    res=[]
    for s in months:
        e=add(s,12*H)
        if e not in I or e not in C or s not in R: continue
        P=400000.; L=0.8*P; r=R[s]/1200; n=360
        pay=L*r/(1-(1+r)**-n)
        y= yA if fixed else yA*(C[s]/I[s])/(C[anchor]/I[anchor])
        rent0=y*P/12
        B=L; buy=0.23*P; rent=0; cash=0.23*P
        for m in range(12*H):
            sm=add(s,m)
            V=P*I[sm]/I[s]
            buy+=pay+c/12*V
            B=B*(1+r)-pay
            rent+=rent0*C[sm]/C[s]
            if tb: cash*=1+T[sm]/1200
        VH=P*I[e]/I[s]; eq=VH*0.94-B
        bcost=buy-eq; rcost=rent-(cash-0.23*P)
        res.append((s,rcost-bcost,y,R[s],I[e]/I[s],C[e]/C[s]))
    return res
for H in (5,10,15):
  for kw in [{},{'tb':True},{'yA':0.04},{'yA':0.06},{'fixed':True}]:
    res=run(H,**kw); win=sum(1 for x in res if x[1]>0)
    b=max(res,key=lambda x:x[1]); wo=min(res,key=lambda x:x[1])
    print(H,kw,len(res),res[0][0],res[-1][0],f"win {win/len(res):.3f}",'best',b[0],round(b[1]),'worst',wo[0],round(wo[1]))
res=run(10)
for x in res[::12]: print(x[0],round(x[1]),round(x[2],4),round(x[3],2),round(x[4],2),round(x[5],2))

